class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        # Initialize a 2D array to store the edit distances between substrings of word1 and word2
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Initialize the base cases
        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j

        # Fill in the rest of the 2D array
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # If the current characters in word1 and word2 are the same, there's no operation needed
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                # Otherwise, consider the minimum cost of insert, delete, and replace operations
                else:
                    dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

        # The minimum edit distance is stored in the bottom-right corner of the 2D array
        return dp[m][n]

