class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        # Create a min heap to store the nodes
        min_heap = []

        # Push the head of each linked list into the min heap
        for i, node in enumerate(lists):
            if node:
                # Heap elements are tuples of (node value, list index, node)
                # This ensures that nodes with the same value are ordered by their list index
                min_heap.append((node.val, i, node))

        # Heapify the min heap
        self.heapify(min_heap)

        # Create a dummy node to serve as the head of the merged list
        dummy = ListNode()
        current = dummy

        # Merge the linked lists
        while min_heap:
            # Extract the node with the smallest value from the min heap
            _, list_index, node = min_heap[0]
            self.heap_pop(min_heap)

            # Add the extracted node to the merged list
            current.next = node
            current = current.next

            # Push the next node from the same list into the min heap
            if node.next:
                self.heap_push(min_heap, (node.next.val, list_index, node.next))

        # Return the merged list
        return dummy.next

    def heapify(self, heap):
        n = len(heap)
        for i in range(n // 2 - 1, -1, -1):
            self.heapify_helper(heap, n, i)

    def heapify_helper(self, heap, n, i):
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and heap[left][0] < heap[smallest][0]:
            smallest = left

        if right < n and heap[right][0] < heap[smallest][0]:
            smallest = right

        if smallest != i:
            heap[i], heap[smallest] = heap[smallest], heap[i]
            self.heapify_helper(heap, n, smallest)

    def heap_push(self, heap, item):
        heap.append(item)
        self.heapify_up(heap, len(heap) - 1)

    def heapify_up(self, heap, i):
        parent = (i - 1) // 2
        if i > 0 and heap[parent][0] > heap[i][0]:
            heap[parent], heap[i] = heap[i], heap[parent]
            self.heapify_up(heap, parent)

    def heap_pop(self, heap):
        if len(heap) == 0:
            return None
        if len(heap) == 1:
            return heap.pop()

        root = heap[0]
        heap[0] = heap.pop()
        self.heapify_helper(heap, len(heap), 0)
        return root

