class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        # Preprocess the board to get a 1D array representing the board
        one_d_array = [0] * (n * n + 1)
        index = 1
        for i in range(n - 1, -1, -1):
            if (n - i) % 2 == 1:
                for j in range(n):
                    one_d_array[index] = board[i][j]
                    index += 1
            else:
                for j in range(n - 1, -1, -1):
                    one_d_array[index] = board[i][j]
                    index += 1

        # BFS
        queue = [1]
        visited = set([1])
        step = 0
        while queue:
            size = len(queue)
            for _ in range(size):
                curr = queue.pop(0)
                if curr == n * n:
                    return step
                for next_pos in range(curr + 1, min(curr + 7, n * n + 1)):
                    # If there's a ladder or snake, jump to its destination
                    dest = one_d_array[next_pos] if one_d_array[next_pos] != -1 else next_pos
                    if dest not in visited:
                        queue.append(dest)
                        visited.add(dest)
            step += 1

        # If we can't reach the destination
        return -1

