    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        # Dictionary to store nodes by their column and row
        nodes = {}

        # Perform DFS to populate the nodes dictionary
        def dfs(node, row, col):
            if node is None:
                return
            if col not in nodes:
                nodes[col] = {}
            if row not in nodes[col]:
                nodes[col][row] = []
            nodes[col][row].append(node.val)
            dfs(node.left, row + 1, col - 1)
            dfs(node.right, row + 1, col + 1)

        dfs(root, 0, 0)

        # Sort the nodes by column, then by row, and finally by value
        result = []
        for col in sorted(nodes.keys()):
            col_result = []
            for row in sorted(nodes[col].keys()):
                col_result.extend(sorted(nodes[col][row]))
            result.append(col_result)

