class Solution:
    def minimum_travel_time(self, n: int, m: int, a: int, b: int, roads: List[Tuple[int, int, int]]) -> List[int]:
        # Create an adjacency list representation of the graph
        graph = [[] for _ in range(n)]
        for u, v, c in roads:
            graph[u-1].append((v-1, c))
            graph[v-1].append((u-1, c))

        # Initialize the parent array for Union-Find
        parent = list(range(n))

        # Define a function to find the parent of a node
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        # Define a function to union two nodes
        def union(x, y):
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        # Sort the roads by their weights
        roads.sort(key=lambda x: x[2])

        # Initialize the minimum spanning tree edges
        mst_edges = []

        # Iterate over the sorted roads to construct the minimum spanning tree
        for u, v, c in roads:
            if find(u-1) != find(v-1):
                mst_edges.append((u-1, v-1, c))
                union(u-1, v-1)

        # Initialize the distance array
        distance = [float('inf')] * n
        distance[0] = 0

        # Perform a BFS traversal to compute the minimum distance
        queue = [0]
        while queue:
            u = queue.pop(0)
            for v, c in graph[u]:
                if (u, v, c) not in mst_edges and (v, u, c) not in mst_edges:
                    continue
                if distance[v] > distance[u] + c:
                    distance[v] = distance[u] + c
                    queue.append(v)

        # Replace the distance with the minimum possible distance using 'a' or 'b'
        for i in range(n):
            distance[i] = min(distance[i], distance[0] + (i > 0) * (a * (i) + b * (n - 1 - i)))

        # However, the above step is not needed as we are directly calculating the shortest path in the MST.
        return distance

