class Solution:
    def max_city_score(self, n: int, m: int, scores: List[int], roads: List[Tuple[int, int]], start: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v in roads:
            graph[u-1].append(v-1)
            graph[v-1].append(u-1)

        visited = set()
        max_score = 0

        stack = [(start-1, -1, scores[start-1])]
        while stack:
            node, parent, score = stack.pop()
            if node not in visited:
                visited.add(node)
                max_score = max(max_score, score)
                for neighbor in graph[node]:
                    if neighbor != parent:
                        stack.append((neighbor, node, score + (0 if neighbor in visited else scores[neighbor])))

        return max_score

