class Solution:
    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node, parent):
            count = usage[node]
            for neighbor in graph[node]:
                if neighbor != parent:
                    count += dfs(neighbor, node)
            return count

        total_usage = sum(usage)
        max_f = 0
        for u, v in edges:
            if u > v:
                u, v = v, u
            count_u = dfs(u, v)
            count_v = total_usage - count_u
            max_f = max(max_f, count_u * count_v)
        return max_f
